(()=>{'use strict';const $=id=>document.getElementById(id),states=['充电中','空闲','已充满','故障','离线'];let selected=1;const inputId=Number(new URLSearchParams(location.search).get('id'));if(Number.isInteger(inputId)&&inputId>=1&&inputId<=36)selected=inputId;const fit=()=>document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1920,innerHeight/1080));fit();addEventListener('resize',fit);function clock(){$('clock').textContent=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date());}clock();setInterval(clock,1000);const panel=(t,b,c='')=>`<section class="panel ${c}"><div class="panel-title"><h2>${t}</h2></div><div class="charger-detail-body">${b}</div></section>`;
function render(){const status=states[(selected-1)%5],active=['充电中','已充满'].includes(status),soc=status==='充电中'?80:status==='已充满'?100:null,plate=active?'陕A0G266':'—',energy=active?'310.2':'—',remaining=status==='充电中'?'0时12分':'—',name=String(selected).padStart(3,'0')+'B号';$('suite-main').innerHTML=`<div class="charger-detail-layout" data-charger-state="${status}"><aside class="charger-detail-side">${panel('充电设备档案',`<label class="charger-select-label">设备编号<select id="detail-charger-select">${Array.from({length:36},(_,i)=>`<option value="${i+1}" ${selected===i+1?'selected':''}>${String(i+1).padStart(3,'0')}B号 / ${states[i%5]}</option>`).join('')}</select></label><div class="charger-portrait"><img src="./assets/energy/iso-charger.svg" alt="直流充电设备"><span>直流充电设备</span></div><div class="charger-profile-title"><h2>${name}</h2><b class="current-status">${status}</b></div><dl class="charger-profile-fields"><div><dt>交直流类型</dt><dd>直流</dd></div><div><dt>设备状态</dt><dd class="current-status">${status}</dd></div></dl>`,'charger-profile-panel')}${panel('所属站点',`<div class="station-name-card"><span>充电站名称</span><h3>特来电屯留小河北<br>重卡充电站</h3></div><a class="charger-related-link" href="./energy-charging-study.html"><span>查看充电站监测</span><b>↗</b></a><div class="charger-snapshot-note">设备状态与充电记录沿用当前页面示例，不连接真实充电设备。</div>`,'charger-station-panel')}</aside><div class="charger-detail-content"><div class="suite-toolbar"><div><h2>充电设备详情</h2><small>${name} / 设备与充电车辆信息</small></div><span class="detail-record-badge">直流充电 / 设备状态</span></div><div class="charger-key-metrics"><article><span>当前 SOC</span><b>${soc===null?'—':soc}<small>%</small></b></article><article><span>充电电量</span><b>${energy}<small>kWh</small></b></article><article><span>剩余时间</span><b class="remaining-reading">${status==='充电中'?'0<small>时</small>12<small>分</small>':'—'}</b></article><article><span>设备状态</span><b class="current-status">${status}</b></article></div>${panel('充电连接关系',`<div class="charger-connection-scene"><div class="connection-object"><img src="./assets/energy/iso-charger.svg" alt="充电设备"><div><span>充电设备</span><b>${name}</b></div></div><div class="connection-path"><span>${status==='充电中'?'正在充电':status==='已充满'?'充电已完成':status==='空闲'?'等待车辆接入':status==='故障'?'设备故障':'设备离线'}</span><div class="energy-line ${status==='充电中'?'flowing':''}"><i></i><i></i><i></i></div><small>${active?'直流连接':'当前无充电连接'}</small></div><div class="connection-object vehicle-object ${active?'':'inactive'}"><img src="./assets/energy/iso-truck.svg" alt="车辆示意"><div><span>充电车辆</span><b>${plate}</b></div></div></div><div class="charger-progress-row"><span>SOC / 充电进度</span><div class="charger-progress-track"><i style="width:${soc||0}%"></i></div><b>${soc===null?'—':soc+'%'}</b></div>`,'charger-connection-panel')}${panel('当前充电记录',`<div class="charging-record-head"><span>设备 ${name}</span><b class="current-status">${status}</b></div><table class="charging-record-table"><thead><tr><th>车牌号</th><th>交直流类型</th><th>充电电量</th><th>SOC</th><th>剩余时间</th></tr></thead><tbody><tr><td>${plate}</td><td>直流</td><td>${energy}${active?' kWh':''}</td><td>${soc===null?'—':soc+'%'}</td><td>${remaining}</td></tr></tbody></table><div class="charging-record-caption">${active?'显示当前设备对应的车辆、电量与充电状态。':'当前设备没有正在进行的充电记录，未提供的字段以“—”表示。'}</div>`,'charging-record-panel')}</div></div>`;$('detail-charger-select').onchange=e=>{selected=Number(e.target.value);render();};}
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{const n=$('toast');n.textContent='请在独立页面中使用浏览器全屏。';n.classList.add('visible');setTimeout(()=>n.classList.remove('visible'),3000);}};render();})();
